// AgentServiceClient is a client for the agent.v1.AgentService service.
type AgentServiceClient interface {
	Health(context.Context, *v1.HealthRequest) (*v1.HealthResponse, error)
	GetIdentity(context.Context, *v1.GetIdentityRequest) (*v1.GetIdentityResponse, error)
	ListSessions(context.Context, *v1.ListSessionsRequest) (*v1.ListSessionsResponse, error)
	CreateSession(context.Context, *v1.CreateSessionRequest) (*v1.CreateSessionResponse, error)
	GetSession(context.Context, *v1.GetSessionRequest) (*v1.GetSessionResponse, error)
	DeleteSession(context.Context, *v1.DeleteSessionRequest) (*v1.DeleteSessionResponse, error)
	ListMessages(context.Context, *v1.ListMessagesRequest) (*v1.ListMessagesResponse, error)
	Prompt(context.Context, *v1.PromptRequest) (AgentServicePromptClientStream, error)
	WatchSession(context.Context, *v1.WatchSessionRequest) (AgentServiceWatchSessionClientStream, error)
	WatchSessions(context.Context, *v1.WatchSessionsRequest) (AgentServiceWatchSessionsClientStream, error)
	Fork(context.Context, *v1.ForkRequest) (*v1.ForkResponse, error)
	Rename(context.Context, *v1.RenameRequest) (*v1.RenameResponse, error)
	SetModel(context.Context, *v1.SetModelRequest) (*v1.SetModelResponse, error)
	Undo(context.Context, *v1.UndoRequest) (*v1.UndoResponse, error)
	MarkRead(context.Context, *v1.MarkReadRequest) (*v1.MarkReadResponse, error)
	// ── session permissions ──────────────────────────────────────────────────
	//
	// A session's authorisations. An extension declares what it can require
	// (PermissionDecl in its manifest); these RPCs record which of those a particular
	// session holds.
	//
	// `params` is OPAQUE: its shape is whatever the extension declared, and neither the
	// agent nor this API interprets it. A session may hold several grants of the same
	// capability with different params — "merge in this repository" and "merge in that
	// one" are two authorisations, not one.
	ListGrants(context.Context, *v1.ListGrantsRequest) (*v1.ListGrantsResponse, error)
	//*
	// ListPermissionStates returns what a session holds AND what it was refused, already joined.
	//
	// THE JOIN BELONGS HERE, NOT IN EVERY CLIENT. A grant is permanent and lives in the relational store;
	// a refusal is a 24-hour reminder and lives in a TTL bucket. That split is right. What was wrong was
	// that the panel called two RPCs and matched rows by (extension, capability) itself — and any second
	// client would have to rediscover that the two are one question asked twice.
	ListPermissionStates(context.Context, *v1.ListPermissionStatesRequest) (*v1.ListPermissionStatesResponse, error)
	//*
	// ListDenials reports the capabilities this session was REFUSED in the last day.
	//
	// A REFUSAL IS CORRECT AND INVISIBLE TO THE PERSON WHO COULD FIX IT. The model reads the error at
	// the moment it happens; the person reads the panel minutes later, with the refusal several tool
	// calls back. This is the list that turns "I cannot do that" into a button.
	//
	// IT IS A REMINDER, NOT A LOG: entries aggregate by capability, and they expire after a day. A list
	// that keeps complaining about something already granted teaches the reader that it is noise.
	ListDenials(context.Context, *v1.ListDenialsRequest) (*v1.ListDenialsResponse, error)
	CreateGrant(context.Context, *v1.CreateGrantRequest) (*v1.CreateGrantResponse, error)
	RevokeGrant(context.Context, *v1.RevokeGrantRequest) (*v1.RevokeGrantResponse, error)
	// ListPermissionDecls publishes what the discovered extensions can require.
	//
	// A client needs this to render a grant form: the params shape comes from the
	// extension, not from the console. Without it a UI could only offer permissions it was
	// hard-coded to know about.
	ListPermissionDecls(context.Context, *v1.ListPermissionDeclsRequest) (*v1.ListPermissionDeclsResponse, error)
	// ── channel subscriptions ────────────────────────────────────────────────
	//
	// What a session LISTENS TO. A subscription is (channel, pattern, wake): the pattern is a
	// NATS subject filter within the channel, and wake decides whether a matching message
	// starts a turn or only lands in the session's context.
	//
	// Every session carries a built-in subscription to `session-channel.<its name>.>` which
	// cannot be removed: that is how anything reaches a session by name.
	ListSubscriptions(context.Context, *v1.ListSubscriptionsRequest) (*v1.ListSubscriptionsResponse, error)
	SubscribeChannel(context.Context, *v1.SubscribeChannelRequest) (*v1.SubscribeChannelResponse, error)
	UnsubscribeChannel(context.Context, *v1.UnsubscribeChannelRequest) (*v1.UnsubscribeChannelResponse, error)
	// ListChannels publishes which channels the discovered extensions publish to, so a client
	// can offer "follow this repository's tags" instead of asking for a pattern.
	ListChannels(context.Context, *v1.ListChannelsRequest) (*v1.ListChannelsResponse, error)
	// ---- groups ----
	//
	// A group is a NAMED SET OF SESSIONS THAT CAN SEE EACH OTHER. It answers one question — "who else
	// is here" — and nothing else: the messages themselves still travel over channels, so a group is a
	// directory plus a fan-out address rather than a second message store.
	//
	// MEMBERSHIP IS THE ONLY PERMISSION. Every call below requires the caller's session to be IN the
	// group; a non-member gets NOT_FOUND rather than PERMISSION_DENIED, because distinguishing the two
	// would let any session enumerate every group in the tenant.
	CreateGroup(context.Context, *v1.CreateGroupRequest) (*v1.CreateGroupResponse, error)
	ListGroups(context.Context, *v1.ListGroupsRequest) (*v1.ListGroupsResponse, error)
	GetGroup(context.Context, *v1.GetGroupRequest) (*v1.GetGroupResponse, error)
	UpdateGroup(context.Context, *v1.UpdateGroupRequest) (*v1.UpdateGroupResponse, error)
	DeleteGroup(context.Context, *v1.DeleteGroupRequest) (*v1.DeleteGroupResponse, error)
	AddGroupMember(context.Context, *v1.AddGroupMemberRequest) (*v1.AddGroupMemberResponse, error)
	RemoveGroupMember(context.Context, *v1.RemoveGroupMemberRequest) (*v1.RemoveGroupMemberResponse, error)
	SetGroupCoordinator(context.Context, *v1.SetGroupCoordinatorRequest) (*v1.SetGroupCoordinatorResponse, error)
	// Send a message FROM A USER to a group. It is delivered to the COORDINATOR only; the coordinator
	// decides how to split the work and addresses members itself with `group-send`. "@" in this design
	// means "the coordinator writes to that session's mailbox", not a string this layer parses.
	SendGroupMessage(context.Context, *v1.SendGroupMessageRequest) (*v1.SendGroupMessageResponse, error)
	//*
	// Ask sends ONE question to a session's context and returns the answer.
	//
	// A SIDE CHANNEL, NOT A TURN. Nothing is written to the session — no message, no step, no read watermark — and a
	// session mid-turn is unaffected. The model runs once, with NO TOOLS, over the history that is already persisted.
	//
	// `AskInGroup` is the same call with the answer posted into a group; this one returns it to the caller.
	Ask(context.Context, *v1.AskRequest) (*v1.AskResponse, error)
	//*
	// AskInGroup asks and posts the answer into a group as a SYSTEM message.
	//
	// The answer is relayed, not sent by the session: attributing it to the session would put words in the transcript it
	// never wrote, and a reader scrolling back would believe it had volunteered them.
	AskInGroup(context.Context, *v1.AskInGroupRequest) (*v1.AskInGroupResponse, error)
	//*
	// ListReplyObligations says who still owes whom an answer in a group.
	//
	// OUTSTANDING ONLY. A reader asking "who has not answered" is not asking for the history of settled ones, and a list
	// that mixed the two would be longer than the transcript it describes.
	ListReplyObligations(context.Context, *v1.ListReplyObligationsRequest) (*v1.ListReplyObligationsResponse, error)
	// A group's transcript, oldest first, paged by `after_seq`.
	ListGroupMessages(context.Context, *v1.ListGroupMessagesRequest) (*v1.ListGroupMessagesResponse, error)
	// Live transcript: retained messages after `since_seq`, then everything new.
	WatchGroup(context.Context, *v1.WatchGroupRequest) (AgentServiceWatchGroupClientStream, error)
	State(context.Context, *v1.StateRequest) (*v1.StateResponse, error)
	Mailbox(context.Context, *v1.MailboxRequest) (*v1.MailboxResponse, error)
	UpdateSettings(context.Context, *v1.UpdateSettingsRequest) (*v1.UpdateSettingsResponse, error)
	Interrupt(context.Context, *v1.InterruptRequest) (*v1.InterruptResponse, error)
	Compact(context.Context, *v1.CompactRequest) (*v1.CompactResponse, error)
	ListProviders(context.Context, *v1.ListProvidersRequest) (*v1.ListProvidersResponse, error)
	ListProvidersCatalog(context.Context, *v1.ListProvidersCatalogRequest) (*v1.ListProvidersCatalogResponse, error)
	RegisterProvider(context.Context, *v1.RegisterProviderRequest) (*v1.RegisterProviderResponse, error)
	DeleteProvider(context.Context, *v1.DeleteProviderRequest) (*v1.DeleteProviderResponse, error)
	TestProvider(context.Context, *v1.TestProviderRequest) (*v1.TestProviderResponse, error)
	ListModels(context.Context, *v1.ListModelsRequest) (*v1.ListModelsResponse, error)
	ListPresets(context.Context, *v1.ListPresetsRequest) (*v1.ListPresetsResponse, error)
	UpsertPreset(context.Context, *v1.UpsertPresetRequest) (*v1.UpsertPresetResponse, error)
	DeletePreset(context.Context, *v1.DeletePresetRequest) (*v1.DeletePresetResponse, error)
	PreviewPreset(context.Context, *v1.PreviewPresetRequest) (*v1.PreviewPresetResponse, error)
	GetConfig(context.Context, *v1.GetConfigRequest) (*v1.GetConfigResponse, error)
	SetConfig(context.Context, *v1.SetConfigRequest) (*v1.SetConfigResponse, error)
	ListTools(context.Context, *v1.ListToolsRequest) (*v1.ListToolsResponse, error)
	GetToolConfig(context.Context, *v1.GetToolConfigRequest) (*v1.GetToolConfigResponse, error)
	SetToolConfig(context.Context, *v1.SetToolConfigRequest) (*v1.SetToolConfigResponse, error)
	SetExtensionConfig(context.Context, *v1.SetExtensionConfigRequest) (*v1.SetExtensionConfigResponse, error)
	ListExtensions(context.Context, *v1.ListExtensionsRequest) (*v1.ListExtensionsResponse, error)
	GetExtensionConfig(context.Context, *v1.GetExtensionConfigRequest) (*v1.GetExtensionConfigResponse, error)
	UploadFile(context.Context, *v1.UploadFileRequest) (*v1.UploadFileResponse, error)
	IngestFile(context.Context, *v1.IngestFileRequest) (*v1.IngestFileResponse, error)
	GetFile(context.Context, *v1.GetFileRequest) (*v1.GetFileResponse, error)
	GetFileMeta(context.Context, *v1.GetFileMetaRequest) (*v1.GetFileMetaResponse, error)
	GetFileStream(context.Context, *v1.GetFileRequest) (AgentServiceGetFileStreamClientStream, error)
	GetAgentConfig(context.Context, *v1.GetAgentConfigRequest) (*v1.GetAgentConfigResponse, error)
}

